mapper.select:
SELECT id,project_task_id,assignee_user_id AS user_id,assigned_by,effective_from,effective_to,reason,version,tenant_id
FROM proj_project_task_assignment WHERE tenant_id=#{query.tenantId} AND project_task_id=#{query.projectTaskId}
  AND deleted=0 ORDER BY effective_from DESC,id DESC LIMIT #{query.offset},#{query.limit}
